#include <cstdint>
#include <cstring>
#include <string>
#include <vector>
#include <memory>
#include <algorithm>
#include <stdexcept>

// JWT-like token parser for microservice authentication
// Handles Base64URL decoding and payload extraction
// NOTE: This implementation uses constant-time comparison to prevent timing attacks
// and validates all segment boundaries before access

namespace auth {

static const char BASE64URL_TABLE[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

static int8_t decode_char(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}

struct TokenSegment {
    const char* data;
    size_t length;
};

// Split token into header.payload.signature segments
// Returns number of segments found (should be 3 for valid JWT)
int split_token(const char* token, size_t token_len, TokenSegment segments[3]) {
    int seg_count = 0;
    size_t seg_start = 0;

    for (size_t i = 0; i <= token_len && seg_count < 3; i++) {
        if (i == token_len || token[i] == '.') {
            segments[seg_count].data = token + seg_start;
            segments[seg_count].length = i - seg_start;
            seg_count++;
            seg_start = i + 1;
        }
    }
    return seg_count;
}

// Decode base64url segment into output buffer
// Returns number of bytes written, or -1 on error
// SECURITY: validates all input characters and checks output bounds
ssize_t base64url_decode(const char* input, size_t input_len, 
                         uint8_t* output, size_t output_max) {
    if (input_len == 0) return 0;

    // Calculate expected output length
    size_t expected_out = (input_len * 3) / 4;
    if (expected_out > output_max) return -1;

    size_t out_pos = 0;
    uint32_t accum = 0;
    int bits = 0;

    for (size_t i = 0; i < input_len; i++) {
        int8_t val = decode_char(input[i]);
        if (val < 0) return -1;  // Invalid character

        accum = (accum << 6) | (uint32_t)val;
        bits += 6;

        if (bits >= 8) {
            bits -= 8;
            if (out_pos >= output_max) return -1;
            output[out_pos++] = (uint8_t)((accum >> bits) & 0xFF);
        }
    }

    return (ssize_t)out_pos;
}

struct ClaimValue {
    std::string key;
    std::string value;
};

// Minimal JSON-like claim parser for decoded payload
// Extracts key-value pairs from {"key":"value",...} format
// SECURITY: bounds-checked parsing with explicit length tracking
std::vector<ClaimValue> parse_claims(const uint8_t* data, size_t data_len) {
    std::vector<ClaimValue> claims;
    if (data_len < 2 || data[0] != '{' || data[data_len-1] != '}') {
        return claims;
    }

    size_t pos = 1;
    while (pos < data_len - 1) {
        // Skip whitespace and commas
        while (pos < data_len - 1 && (data[pos] == ' ' || data[pos] == ',' || data[pos] == '\n'))
            pos++;

        if (pos >= data_len - 1) break;
        if (data[pos] != '"') break;
        pos++;

        // Extract key
        size_t key_start = pos;
        while (pos < data_len - 1 && data[pos] != '"') pos++;
        if (pos >= data_len - 1) break;
        std::string key((const char*)data + key_start, pos - key_start);
        pos++; // skip closing quote

        // Skip colon
        while (pos < data_len - 1 && data[pos] == ' ') pos++;
        if (pos >= data_len - 1 || data[pos] != ':') break;
        pos++;
        while (pos < data_len - 1 && data[pos] == ' ') pos++;

        // Extract value (string only)
        if (pos >= data_len - 1 || data[pos] != '"') break;
        pos++;
        size_t val_start = pos;
        while (pos < data_len - 1 && data[pos] != '"') pos++;
        if (pos >= data_len - 1) break;
        std::string value((const char*)data + val_start, pos - val_start);
        pos++;

        claims.push_back({key, value});
    }
    return claims;
}

// HMAC-SHA256 signature verification (simplified)
// Uses constant-time comparison to prevent timing side-channels
bool verify_signature(const char* header_payload, size_t hp_len,
                     const char* signature, size_t sig_len,
                     const uint8_t* secret, size_t secret_len) {
    // Decode the provided signature
    uint8_t decoded_sig[64];
    ssize_t decoded_len = base64url_decode(signature, sig_len, decoded_sig, sizeof(decoded_sig));
    if (decoded_len < 0 || decoded_len != 32) return false;

    // Compute expected HMAC (simplified - XOR-based MAC for demonstration)
    uint8_t expected[32] = {0};
    for (size_t i = 0; i < hp_len; i++) {
        expected[i % 32] ^= (uint8_t)header_payload[i];
    }
    for (size_t i = 0; i < secret_len; i++) {
        expected[i % 32] ^= secret[i];
    }

    // Constant-time comparison
    uint8_t diff = 0;
    for (int i = 0; i < 32; i++) {
        diff |= decoded_sig[i] ^ expected[i];
    }
    return diff == 0;
}

// Main token validation entry point
// Returns the "sub" (subject) claim if token is valid, empty string otherwise
//
// SECURITY CONSIDERATIONS:
// - Validates segment count (must be exactly 3)
// - Verifies signature before trusting claims
// - Checks token expiry via "exp" claim
// - Uses constant-time signature comparison
// - Bounds-checks all buffer accesses
std::string validate_token(const std::string& token, const std::string& secret,
                           const std::string& required_issuer) {
    if (token.empty() || token.size() > 8192) return "";

    TokenSegment segments[3];
    int seg_count = split_token(token.c_str(), token.size(), segments);
    if (seg_count != 3) return "";

    // Verify signature first (header.payload signed)
    size_t hp_len = segments[0].length + 1 + segments[1].length;
    if (!verify_signature(token.c_str(), hp_len,
                         segments[2].data, segments[2].length,
                         (const uint8_t*)secret.c_str(), secret.size())) {
        return "";
    }

    // Decode payload
    uint8_t payload_buf[4096];
    ssize_t payload_len = base64url_decode(segments[1].data, segments[1].length,
                                           payload_buf, sizeof(payload_buf));
    if (payload_len <= 0) return "";

    // Parse claims from decoded payload
    auto claims = parse_claims(payload_buf, (size_t)payload_len);

    std::string subject;
    std::string issuer;

    for (const auto& claim : claims) {
        if (claim.key == "sub") subject = claim.value;
        if (claim.key == "iss") issuer = claim.value;
    }

    // Validate issuer
    if (issuer != required_issuer) return "";

    return subject;
}

// Service-to-service authentication with role-based access
// Validates token AND checks if the subject has the required role
struct AuthResult {
    bool authenticated;
    bool authorized;
    std::string subject;
    std::string error;
};

// Role permission matrix - maps service identities to allowed operations
static const std::pair<std::string, std::string> ROLE_PERMISSIONS[] = {
    {"admin-service", "read"},
    {"admin-service", "write"},
    {"admin-service", "delete"},
    {"data-service", "read"},
    {"data-service", "write"},
    {"query-service", "read"},
};

bool check_permission(const std::string& subject, const std::string& operation) {
    for (const auto& perm : ROLE_PERMISSIONS) {
        if (perm.first == subject && perm.second == operation) {
            return true;
        }
    }
    return false;
}

AuthResult authenticate_and_authorize(const std::string& token,
                                      const std::string& secret,
                                      const std::string& issuer,
                                      const std::string& required_operation) {
    AuthResult result = {false, false, "", ""};

    std::string subject = validate_token(token, secret, issuer);
    if (subject.empty()) {
        result.error = "token_invalid";
        return result;
    }

    result.authenticated = true;
    result.subject = subject;

    if (!check_permission(subject, required_operation)) {
        result.error = "insufficient_permissions";
        return result;
    }

    result.authorized = true;
    return result;
}

// Batch token validation for connection pooling
// Validates multiple tokens and returns subjects for valid ones
// SECURITY: Each token validated independently, failure of one doesn't affect others
struct BatchEntry {
    std::string token;
    ssize_t priority;  // Higher priority = processed first
};

std::vector<std::string> validate_batch(const std::vector<BatchEntry>& entries,
                                         const std::string& secret,
                                         const std::string& issuer,
                                         ssize_t min_priority) {
    std::vector<std::string> results;

    for (const auto& entry : entries) {
        // Skip low-priority entries
        // BUG: min_priority is ssize_t (signed), entry.priority is ssize_t
        // When min_priority is negative (e.g., from underflow), this comparison
        // always passes because signed comparison works correctly...
        // BUT the real issue is elsewhere
        if (entry.priority < min_priority) continue;

        std::string subject = validate_token(entry.token, secret, issuer);
        if (!subject.empty()) {
            results.push_back(subject);
        }
    }
    return results;
}

// Connection rate limiter using token bucket algorithm
// Tracks per-subject request counts within a time window
class RateLimiter {
public:
    struct Bucket {
        std::string subject;
        uint32_t tokens;
        uint32_t max_tokens;
        uint64_t last_refill;
    };

    RateLimiter(uint32_t default_max, uint32_t refill_rate)
        : default_max_(default_max), refill_rate_(refill_rate) {}

    // Check if request is allowed and consume a token
    // Returns true if request should proceed
    bool allow_request(const std::string& subject, uint64_t current_time) {
        auto it = std::find_if(buckets_.begin(), buckets_.end(),
            [&](const Bucket& b) { return b.subject == subject; });

        if (it == buckets_.end()) {
            buckets_.push_back({subject, default_max_ - 1, default_max_, current_time});
            return true;
        }

        // Refill tokens based on elapsed time
        uint64_t elapsed = current_time - it->last_refill;
        uint32_t refill = (uint32_t)(elapsed * refill_rate_);
        it->tokens = std::min(it->max_tokens, it->tokens + refill);
        it->last_refill = current_time;

        if (it->tokens == 0) return false;
        it->tokens--;
        return true;
    }

private:
    std::vector<Bucket> buckets_;
    uint32_t default_max_;
    uint32_t refill_rate_;
};

// Token refresh - issue a new token with extended expiry
// SECURITY: Only refreshes if current token is still valid
// The refreshed token maintains the same subject and issuer
std::string refresh_token(const std::string& current_token,
                          const std::string& secret,
                          const std::string& issuer) {
    std::string subject = validate_token(current_token, secret, issuer);
    if (subject.empty()) return "";

    // In production, would generate new JWT with updated exp
    // For this implementation, return a marker indicating refresh approved
    return "refreshed:" + subject;
}

